{
  "case_id": "C04",
  "audience": "Coaches and sports-science students",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "The problem",
      "narration": "Iron deficiency without anaemia shows up in fifteen to thirty-five per cent of adolescent endurance athletes. And daily iron pushes hepcidin up for a day or more, which blunts absorption of the next dose.",
      "on_screen": "Title: 'Iron dosing in adolescent athletes'. Simple curve of hepcidin rising after a dose and falling over 48 hours.",
      "claim_refs": ["SYN-C04/background/prevalence-15-35pct", "SYN-C04/background/hepcidin-24h-blockade"]
    },
    {
      "beat": "The trial",
      "narration": "So this double-blind randomised trial gave 214 athletes aged fifteen to eighteen, all with ferritin below thirty micrograms per litre, either sixty milligrams of elemental iron on alternate days or matching placebo, for twelve weeks.",
      "on_screen": "Flow diagram: 214 randomised, 107 iron / 107 placebo; callout 'ferritin < 30 ug/L', 'alternate days', '12 weeks'.",
      "claim_refs": ["SYN-C04/abstract/design-n214", "SYN-C04/methods/dose-60mg-alternate-day", "SYN-C04/methods/blinding"]
    },
    {
      "beat": "What changed",
      "narration": "Ferritin rose 18.4 micrograms per litre on iron versus 2.1 on placebo: a between-group difference of 16.3, confidence interval 12.9 to 19.7. Haemoglobin shifted only 1.5 grams per litre, which is expected in athletes who were not anaemic.",
      "on_screen": "Two bars for ferritin change with the 16.3 difference and its CI; small side panel showing the 1.5 g/L haemoglobin difference.",
      "claim_refs": ["SYN-C04/results/ferritin-between-group-16.3", "SYN-C04/results/haemoglobin-between-group-1.5"]
    },
    {
      "beat": "Tolerability",
      "narration": "Gut side effects were real but modest: twenty-one of 107 athletes on iron reported them, against nine of 107 on placebo. Adherence, by pill count, was ninety-one per cent.",
      "on_screen": "Icon array 21/107 vs 9/107 for gastrointestinal adverse events; adherence badge '91%'.",
      "claim_refs": ["SYN-C04/abstract/gi-adverse-events", "SYN-C04/methods/adherence-91pct"]
    },
    {
      "beat": "Read it carefully",
      "narration": "Two caveats before you act on this. It applies to athletes who were already below that thirty-microgram threshold, not to everyone. And no performance endpoint was measured, so a better ferritin here is not proven faster running.",
      "on_screen": "Two lines on a plain card: 'Enrolled only if ferritin < 30 ug/L' and 'No performance outcome measured'. Footer: ISRCTN-SYN-C04.",
      "claim_refs": ["SYN-C04/limitations/ferritin-threshold-30", "SYN-C04/limitations/no-performance-endpoint", "SYN-C04/conclusion"]
    }
  ]
}
